# Generated by Phase: IMPLEMENT | Feature: #114
"""Dependency allowlist check — QA-PRE-1 (#114, PLAW-10).

Every DIRECT dependency the project declares is checked at the version its lockfile RESOLVED (never the
declared range) against `config/allowlist.json`: denied → red; unlisted → red; resolved outside the listed
range → red. The stack answers in `docs/setup.md` (`backend.runtime` Q5, `frontend.framework` Q9) select the
readers — the readers live here, never in a configuration table. Missing constitution, allowlist, manifest
or lockfile, an undeclared stack, a stack without a reader: red, in plain language (LAW-08).

Allowlist: `{metadata, <category>: [{name, version, reason?}]}` — a category whose key ends in `denied` is a
deny list, every other category allows; a deny wins over an allow. Names are registry names, compared
case-insensitively; Python also folds `-`, `_`, `.` (PEP 503); Java names are `group:artifact`. Ranges: `*`,
comparators (`>=1.2,<2`, `==1.4.0`, `!=`), `^`, `~`, `~=`, `1.2.*`. When a lockfile resolves a name at several
versions, every one must fall in the range. A pom version a parent or BOM manages passes only a `*` entry.

Seeding (`--seed`): Q26's answers (`docs/setup.md → dependencies.backend / dependencies.frontend / dependencies.denied`)
and, with `--tools FILE`, the tools a platform pack brings (`{"tools": [{"name", "version"}]}`) merge into the
allowlist; an entry already listed is kept as written, a denied name is never seeded as allowed, an
unreadable range stops the seed. Stdlib only (tomllib: Python ≥ 3.11).
"""
from __future__ import annotations

import fnmatch
import json
import os
import re
from pathlib import Path

from gates.common import GateFault, constitution_path, read_frontmatter

ALLOWLIST = "config/allowlist.json"
SETUP = "docs/setup.md"
SKIP_DIRS = {".git", "node_modules", ".venv", "venv", "vendor", "target", "dist", "build", "_build", "deps", ".tox", "bin", "obj", "__pycache__"}
MANAGED = "managed"     # a pom version a parent or BOM decides — the pom does not say which


# ─── names + versions ───────────────────────────────────────────────────────────

def key(name: str, fold: bool = False) -> str:
    """Matching key: case-insensitive; `fold` (Python, PEP 503) also equates `-`, `_` and `.`."""
    n = str(name).strip().lower()
    return re.sub(r"[-_.]+", "-", n) if fold else n


def ver(v: str) -> tuple:
    m = re.match(r"\s*v?(\d+(?:\.\d+)*)", v or "")
    if not m:
        raise ValueError(v)
    return tuple(int(x) for x in m.group(1).split("."))


def _cmp(a: tuple, b: tuple) -> int:
    n = max(len(a), len(b))
    a, b = a + (0,) * (n - len(a)), b + (0,) * (n - len(b))
    return (a > b) - (a < b)


def _bump(t: tuple, at: int) -> tuple:
    t = t + (0,) * (at + 1 - len(t))
    return t[:at] + (t[at] + 1,)


def _parts(spec: str) -> list[tuple[str, str]]:
    """`spec` → [(operator, version)]; ValueError when any part cannot be read. `*` → []."""
    spec = (spec or "*").strip()
    if spec in ("*", "", "any"):
        return []
    out = []
    for part in [p for p in re.split(r"\s*,\s*|\s+(?=[<>=!~^])", spec) if p]:
        m = re.fullmatch(r"(>=|<=|==|!=|~=|>|<|=|\^|~)?\s*(v?\d+(?:\.\d+)*(?:\.\*)?)", part)
        if not m:
            raise ValueError(spec)
        out.append((m.group(1) or "==", m.group(2)))
    return out


def in_range(resolved: str, spec: str) -> bool:
    """True when `resolved` satisfies `spec`; ValueError when either cannot be read."""
    parts = _parts(spec)
    if not parts:
        return True
    v = ver(resolved)
    for op, raw in parts:
        if raw.endswith(".*"):
            pre = ver(raw[:-2])
            if (v[:len(pre)] == pre) != (op != "!="):
                return False
            continue
        b = ver(raw)
        if op in ("^", "~", "~="):
            at = (next((i for i, x in enumerate(b) if x), len(b) - 1) if op == "^"
                  else min(1, len(b) - 1) if op == "~" else max(len(b) - 2, 0))
            if not (_cmp(v, b) >= 0 and _cmp(v, _bump(b, at)) < 0):
                return False
            continue
        c = _cmp(v, b)
        if not {"==": c == 0, "=": c == 0, "!=": c != 0, ">=": c >= 0, "<=": c <= 0, ">": c > 0, "<": c < 0}[op]:
            return False
    return True


# ─── files ──────────────────────────────────────────────────────────────────────

def _walk(repo: Path, names: set[str]) -> list[Path]:
    """Manifests by file name or glob, outside dependency, build and hidden directories."""
    out = []
    for d, dirs, files in os.walk(repo):
        dirs[:] = sorted(x for x in dirs if x not in SKIP_DIRS and not x.startswith("."))
        out += [Path(d) / f for f in sorted(files) if any(fnmatch.fnmatchcase(f, n) for n in names)]
    return out


def _near(manifest: Path, repo: Path, names: tuple) -> Path | None:
    d = manifest.parent
    while True:
        for n in names:
            if (d / n).is_file():
                return d / n
        if d == repo or repo not in d.parents:
            return None
        d = d.parent


def _toml(p: Path) -> dict:
    try:
        import tomllib
    except ImportError:
        raise GateFault(f"{p.name} is TOML and this host's python3 has no tomllib — use Python 3.11 or newer") from None
    try:
        return tomllib.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"{p} is not readable TOML ({e})") from None


def _json(p: Path) -> dict:
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"{p} is not readable JSON ({e})") from None
    return d if isinstance(d, dict) else {}


def _pep508(s: str) -> str:
    m = re.match(r"\s*([A-Za-z0-9][A-Za-z0-9._-]*)", s)
    return m.group(1) if m else ""


# ─── readers: each returns [(manifest, name | None, resolved, note)] ───────────
# resolved: a version, a list of versions (a lockfile holding several), MANAGED, or None = the lockfile does
# not resolve it; note = the plain-language reason. name None = the manifest itself cannot be checked (note).

def _lock_packages(lock: Path, fold: bool) -> dict:
    """`[[package]] name / version` lockfiles (uv.lock, poetry.lock, Cargo.lock) → {key: [versions]}."""
    out: dict = {}
    for p in _toml(lock).get("package", []):
        out.setdefault(key(p.get("name", ""), fold), []).append(str(p.get("version", "")))
    return out


def read_npm(repo: Path):
    rows = []
    for man in _walk(repo, {"package.json"}):
        pj = _json(man)
        optional_peer = {n for n, m in (pj.get("peerDependenciesMeta") or {}).items() if isinstance(m, dict) and m.get("optional")}
        direct = {n: s for sec in ("peerDependencies", "optionalDependencies", "devDependencies", "dependencies")
                  for n, s in (pj.get(sec) or {}).items() if not (sec == "peerDependencies" and n in optional_peer)}
        if not direct:
            continue
        lock = _near(man, repo, ("package-lock.json", "pnpm-lock.yaml", "yarn.lock"))
        if lock is None:
            rows += [(man, n, None, "no lockfile (package-lock.json, pnpm-lock.yaml or yarn.lock) — commit it") for n in direct]
            continue
        data = _json(lock) if lock.name == "package-lock.json" else lock.read_text(encoding="utf-8")
        rel = man.parent.relative_to(lock.parent).as_posix()
        for n, spec in direct.items():
            rows.append((man, n, _npm_resolved(lock.name, data, rel, n, str(spec)), f"{lock.name} does not resolve it"))
    return rows


def _npm_resolved(kind: str, data, rel: str, name: str, spec: str):
    if kind == "package-lock.json":
        pre = "" if rel == "." else rel + "/"
        for k in (f"{pre}node_modules/{name}", f"node_modules/{name}"):
            if k in data.get("packages", {}):
                return data["packages"][k].get("version")
        return data.get("dependencies", {}).get(name, {}).get("version")
    text = data
    if kind == "pnpm-lock.yaml":
        imp = re.search(r"^importers:\n((?:[ \t]+.*\n|\n)*)", text, re.M)
        scope = imp.group(1) if imp else text
        blk = re.search(r"^  " + re.escape(rel if rel != "." else ".") + r":\n((?:    .*\n|\n)*)", scope, re.M) if imp else None
        body = blk.group(1) if blk else scope
        m = re.search(r"^\s+'?" + re.escape(name) + r"'?:\n\s+specifier:.*\n\s+version: '?([^\s'(]+)", body, re.M)
        return m.group(1) if m else None
    for head, body in re.findall(r'^(\S.*):\n((?:[ \t]+.*\n?)+)', text, re.M):     # yarn.lock (classic and berry)
        for h in (x.strip().strip('"') for x in head.split(",")):
            at = h.rfind("@")
            if at > 0 and h[:at] == name and h[at + 1:].removeprefix("npm:") == spec:
                m = re.search(r'^\s+version:? "?([^"\s]+)', body, re.M)
                return m.group(1) if m else None
    return None


def read_python(repo: Path):
    rows = []
    for man in _walk(repo, {"pyproject.toml", "Pipfile"}):
        if man.name == "Pipfile":
            d = _toml(man)
            names = [*d.get("packages", {}), *d.get("dev-packages", {})]
            lock = man.with_name("Pipfile.lock")
            if not lock.is_file():
                rows += [(man, n, None, "no Pipfile.lock — commit it") for n in names]
                continue
            lk = _json(lock)
            got = {key(k, True): v.get("version", "").lstrip("=") for sec in ("default", "develop") for k, v in lk.get(sec, {}).items()}
            rows += [(man, n, got.get(key(n, True)), "Pipfile.lock does not resolve it") for n in names]
            continue
        d = _toml(man)
        proj, poetry = d.get("project", {}), d.get("tool", {}).get("poetry", {})
        names = [_pep508(s) for s in proj.get("dependencies", [])]
        names += [_pep508(s) for grp in proj.get("optional-dependencies", {}).values() for s in grp]
        names += [_pep508(s) for grp in d.get("dependency-groups", {}).values() for s in grp if isinstance(s, str)]
        names += [n for n in {**poetry.get("dependencies", {}), **poetry.get("dev-dependencies", {})} if n.lower() != "python"]
        names += [n for g in poetry.get("group", {}).values() for n in g.get("dependencies", {})]
        names = [n for n in dict.fromkeys(names) if n]
        if not names:
            continue
        lock = _near(man, repo, ("uv.lock", "poetry.lock"))
        if lock is None:
            rows += [(man, n, None, "no lockfile (uv.lock or poetry.lock) — commit it") for n in names]
            continue
        got = _lock_packages(lock, True)
        rows += [(man, n, got.get(key(n, True)), f"{lock.name} does not resolve it") for n in names]
    for req in _walk(repo, {"requirements.txt", "requirements-dev.txt"}):
        for line in req.read_text(encoding="utf-8").splitlines():
            line = line.split("#", 1)[0].strip()
            if not line or line.startswith("-"):
                continue
            m = re.match(r"([A-Za-z0-9][A-Za-z0-9._-]*)(?:\[[^\]]*\])?\s*==\s*([^\s;]+)", line)
            rows.append((req, m.group(1), m.group(2), "") if m else (req, _pep508(line), None, "not pinned with == — the resolved version is unknown"))
    return rows


def read_go(repo: Path):
    rows = []
    for man in _walk(repo, {"go.mod"}):
        text = man.read_text(encoding="utf-8")
        reqs = re.findall(r"^require[ \t]+([^\s(]\S*)[ \t]+(\S+)(.*)$", text, re.M)
        for blk in re.findall(r"^require\s*\(\n(.*?)^\)", text, re.M | re.S):
            reqs += re.findall(r"^[ \t]*(\S+)[ \t]+(\S+)(.*)$", blk, re.M)
        rows += [(man, n, v, "") for n, v, tail in reqs if "// indirect" not in tail and not n.startswith("//")]
    return rows


def read_dotnet(repo: Path):
    rows = []
    for man in _walk(repo, {"*.csproj", "*.fsproj"}):
        lock = man.with_name("packages.lock.json")
        if not lock.is_file():
            rows.append((man, None, None, "no packages.lock.json — set RestorePackagesWithLockFile and commit it"))
            continue
        got: dict = {}
        for deps in _json(lock).get("dependencies", {}).values():       # one block per target framework
            for n, e in deps.items():
                if e.get("type") == "Direct":
                    got.setdefault(n, {})[e.get("resolved")] = None
        rows += [(lock, n, [v for v in vs if v], "packages.lock.json does not resolve it") for n, vs in got.items()]
    return rows


def read_rust(repo: Path):
    rows = []
    for man in _walk(repo, {"Cargo.toml"}):
        d = _toml(man)
        tables = [d, d.get("workspace", {}), *d.get("target", {}).values()]
        names = list(dict.fromkeys(n for t in tables for sec in ("dependencies", "dev-dependencies", "build-dependencies") for n in t.get(sec, {})))
        if not names:
            continue
        lock = _near(man, repo, ("Cargo.lock",))
        got = _lock_packages(lock, False) if lock else {}
        rows += [(man, n, got.get(key(n)), "Cargo.lock does not resolve it" if lock else "no Cargo.lock — commit it") for n in names]
    return rows


def read_ruby(repo: Path):
    rows = []
    for man in _walk(repo, {"Gemfile"}):
        lock = man.with_name("Gemfile.lock")
        if not lock.is_file():
            rows.append((man, None, None, "no Gemfile.lock — commit it"))
            continue
        text = lock.read_text(encoding="utf-8")
        specs = dict(re.findall(r"^    ([A-Za-z0-9_.-]+) \(([^)\s-]+)[^)]*\)$", text, re.M))
        dep = re.search(r"^DEPENDENCIES\n((?:  .*\n?)+)", text, re.M)
        names = re.findall(r"^  ([A-Za-z0-9_.-]+)", dep.group(1), re.M) if dep else []
        rows += [(lock, n, specs.get(n), "Gemfile.lock does not resolve it") for n in names]
    return rows


def read_php(repo: Path):
    rows = []
    for man in _walk(repo, {"composer.json"}):
        cj = _json(man)
        names = [n for n in {**cj.get("require", {}), **cj.get("require-dev", {})} if n != "php" and not n.startswith("ext-")]
        lock = man.with_name("composer.lock")
        if not lock.is_file():
            rows += [(man, n, None, "no composer.lock — commit it") for n in names]
            continue
        lk = _json(lock)
        got = {p["name"]: str(p.get("version", "")).lstrip("v") for sec in ("packages", "packages-dev") for p in lk.get(sec, [])}
        rows += [(man, n, got.get(n), "composer.lock does not resolve it") for n in names]
    return rows


def read_elixir(repo: Path):
    rows = []
    for man in _walk(repo, {"mix.exs"}):
        text = man.read_text(encoding="utf-8")
        body = re.search(r"\bdefp?\s+deps\b(.*?)(?=\n\s*defp?\s|\Z)", text, re.S)
        names = re.findall(r"\{:([a-z0-9_]+)\s*,", body.group(1) if body else text)   # inline deps: the whole file
        lock = man.with_name("mix.lock")
        got = dict(re.findall(r'^\s*"([a-z0-9_]+)": \{:hex, :[a-z0-9_]+, "([^"]+)"', lock.read_text(encoding="utf-8"), re.M)) if lock.is_file() else {}
        rows += [(man, n, got.get(n), "mix.lock does not resolve it" if lock.is_file() else "no mix.lock — commit it") for n in names]
    return rows


GRADLE_CONF = (r"\b(?:\w*(?:[Ii]mplementation|Api|[Cc]ompileOnly|[Rr]untimeOnly|[Aa]nnotationProcessor)|api|kapt\w*|ksp\w*|"
               r"coreLibraryDesugaring|developmentOnly)\s*\(?\s*(?:(?:enforcedP|p)latform\s*\(\s*)?")
GRADLE_STRING_OR_COMMENT = re.compile(r"""('(?:\\.|[^'\\\n])*'|"(?:\\.|[^"\\\n])*")|//[^\n]*|/\*.*?\*/""", re.S)


def read_java(repo: Path):
    rows = []
    for man in _walk(repo, {"build.gradle", "build.gradle.kts"}):
        text = GRADLE_STRING_OR_COMMENT.sub(lambda m: m.group(1) or "", man.read_text(encoding="utf-8"))   # strings kept: '**/*.yml' is no comment
        lock = man.with_name("gradle.lockfile")
        got: dict = {}
        for n, v in (re.findall(r"^([\w.\-]+:[\w.\-]+):([^=\s]+)=", lock.read_text(encoding="utf-8"), re.M) if lock.is_file() else []):
            got.setdefault(n, []).append(v)
        rows += [(man, None, None, f"{ref} is a version-catalog reference, which this check does not read — declare it as 'group:artifact:version'")
                 for ref in dict.fromkeys(re.findall(GRADLE_CONF + r"(libs\.[\w.]+)", text))]
        rows += [(man, n, got.get(n), "gradle.lockfile does not resolve it" if lock.is_file() else "no gradle.lockfile — enable dependency locking and commit it")
                 for n in dict.fromkeys(re.findall(GRADLE_CONF + r"""['"]([\w.\-]+:[\w.\-]+)""", text)
                                        + [f"{g}:{a}" for g, a in re.findall(GRADLE_CONF + r"""group\s*:\s*['"]([\w.\-]+)['"]\s*,\s*name\s*:\s*['"]([\w.\-]+)""", text)])]
    for man in _walk(repo, {"pom.xml"}):
        text = re.sub(r"<!--.*?-->", "", man.read_text(encoding="utf-8"), flags=re.S)
        pm = re.search(r"<properties>(.*?)</properties>", text, re.S)
        props = dict(re.findall(r"<([\w.\-]+)>([^<${}]+)</\1>", pm.group(1))) if pm else {}
        for blk in re.findall(r"<dependency>(.*?)</dependency>", re.sub(r"<dependencyManagement>.*?</dependencyManagement>", "", text, flags=re.S), re.S):
            g, a, v = (re.search(rf"<{t}>([^<]+)</{t}>", blk) for t in ("groupId", "artifactId", "version"))
            if not (g and a):
                continue
            raw = v.group(1).strip() if v else None
            raw = props.get(raw[2:-1]) if raw and raw.startswith("${") else raw
            rows.append((man, f"{g.group(1)}:{a.group(1)}", raw or MANAGED, ""))
    return rows


BACKEND_READERS = {"Node.js": read_npm, "Python": read_python, "Java": read_java, "Go": read_go, ".NET": read_dotnet,
                   "Ruby": read_ruby, "PHP": read_php, "Rust": read_rust, "Elixir": read_elixir}
FRONTEND_READERS = {"React": read_npm, "Vue.js": read_npm, "Angular": read_npm, "Svelte": read_npm, "Solid": read_npm}
NONE = ("", "None", "None (API only)")
SKIPPED_BY_SCOPE = {"backend.runtime": ("frontend-only",), "frontend.framework": ("backend-only", "integration")}   # discovery TIER_1_STACK


def readers() -> dict:
    return {"backend.runtime": sorted(BACKEND_READERS), "frontend.framework": sorted(FRONTEND_READERS)}


# ─── the check ──────────────────────────────────────────────────────────────────

def _entries(allow: dict):
    for cat, items in allow.items():
        if cat == "metadata" or not isinstance(items, list):
            continue
        for e in items:
            if isinstance(e, dict) and e.get("name"):
                yield cat.endswith("denied"), e


def _lookup(allow: dict, name: str, fold: bool):
    hits = [(d, e) for d, e in _entries(allow) if key(e["name"], fold) == key(name, fold)]
    return [e for d, e in hits if d], [e for d, e in hits if not d]


def _stack(repo: Path) -> dict:
    p = repo / SETUP
    return read_frontmatter(p) if p.is_file() else {}


def _answer(fm: dict, dotted: str):
    section, field = dotted.split(".")
    v = fm.get(section)
    return v.get(field) if isinstance(v, dict) else None


def _any_version(e: dict) -> bool:
    return str(e.get("version", "*")).strip() in ("*", "", "any")


def check(repo: Path) -> list[str]:
    if constitution_path(repo) is None:
        return ["docs/constitution.md is missing — the allowlist mandate (PLAW-10) has no home. Resolution: run SETUP --generate."]
    if not (repo / ALLOWLIST).is_file():
        return [f"{ALLOWLIST} is missing — nothing says which dependencies are allowed. Resolution: python3 scripts/gate.py dependencies --seed."]
    allow = _json(repo / ALLOWLIST)
    fm = _stack(repo)
    chosen, out = [], []
    for dotted, q, table in (("backend.runtime", "Q5", BACKEND_READERS), ("frontend.framework", "Q9", FRONTEND_READERS)):
        lit = _answer(fm, dotted)
        if lit is None and fm.get("project_scope") in SKIPPED_BY_SCOPE[dotted]:
            continue                                                      # the scope skipped the question
        lit = lit if lit is None or isinstance(lit, str) else str(lit)   # a list or map is no reader's literal
        if lit is None:
            out.append(f"{SETUP} does not record {dotted} — the dependency readers cannot be chosen. Resolution: complete SETUP discovery {q}.")
        elif lit in NONE:
            continue
        elif lit not in table:
            out.append(f"no dependency reader for {dotted} '{lit}' — this stack cannot be checked. Resolution: declare a reader (SETUP discovery § verification coverage).")
        elif table[lit] not in chosen:
            chosen.append(table[lit])
    seen = set()
    for reader in chosen:
        rows = reader(repo)
        if not rows:
            out.append(f"no {reader.__name__[5:]} manifest found — the declared stack has no dependencies to check. Resolution: commit the manifest and its lockfile.")
        fold = reader is read_python
        for man, name, resolved, note in rows:
            where = man.relative_to(repo).as_posix()
            if name is None:
                out.append(f"{where}: {note}.")
                continue
            if (where, name) in seen:
                continue
            seen.add((where, name))
            denied, allowed = _lookup(allow, name, fold)
            versions = [resolved] if isinstance(resolved, str) else list(dict.fromkeys(resolved or []))
            if denied:
                out.append(f"{where}: {name} is denied ({denied[0].get('reason') or 'no reason given'}). Resolution: remove it.")
            elif not allowed:
                out.append(f"{where}: {name} is not on the allowlist. Resolution: add it through BLUEPRINT --refine and its ADR, or remove it.")
            elif resolved == MANAGED:
                if not any(_any_version(e) for e in allowed):
                    out.append(f"{where}: {name} — its version is managed by a parent pom or a BOM, which this check does not read. Resolution: pin it in the pom, or allow the name with *.")
            elif not versions:
                out.append(f"{where}: {name} — {note}.")
            else:
                try:
                    bad = [v for v in versions if not any(in_range(v, e.get("version", "*")) for e in allowed)]
                except ValueError:
                    out.append(f"{where}: {name} {', '.join(versions)} — the allowlist range or the resolved version cannot be read. Resolution: write the range as >=X,<Y.")
                    continue
                if bad:
                    out.append(f"{where}: {name} resolves to {', '.join(bad)}, outside the allowlisted {', '.join(str(e.get('version')) for e in allowed)}. Resolution: pin a listed version or widen the range through its ADR.")
    return out


# ─── seeding ────────────────────────────────────────────────────────────────────

def _entry(x, where: str) -> dict:
    if isinstance(x, dict) and x.get("name"):
        e = {k: v for k, v in x.items() if k in ("name", "version", "reason")} | {"version": str(x.get("version", "*"))}
    elif isinstance(x, str) and x.strip():
        name, _, rng = x.strip().partition(" ")
        e = {"name": name, "version": rng.strip() or "*"}
    else:
        raise GateFault(f"{where}: {x!r} is not a dependency entry — write `name` or `name <range>`.")
    try:
        _parts(e["version"])
    except ValueError:
        raise GateFault(f"{where}: '{e['name']} {e['version']}' — the range cannot be read. Resolution: write it as >=X,<Y, ^X.Y or *.") from None
    return e


def _items(v, where: str) -> list:
    if v is None or isinstance(v, list):
        return v or []
    if isinstance(v, str):
        return [v]
    raise GateFault(f"{where}: {v!r} is not a list of dependencies — write `[name, name <range>]`.")


def seed(repo: Path, tools: Path | None = None) -> dict:
    p = repo / ALLOWLIST
    allow = _json(p) if p.is_file() else {}
    allow.setdefault("metadata", {"generated_by": "gate.py dependencies --seed (SETUP --generate / --upgrade)",
                                  "updated_via": "BLUEPRINT --refine + ADR", "policy": "allowlist"})
    deps = _stack(repo).get("dependencies")
    deps = deps if isinstance(deps, dict) else {}
    # denied first: a name the answers deny is never seeded as allowed (a deny wins)
    adds = {c: (SETUP, _items(deps.get(c), f"{SETUP} dependencies.{c}")) for c in ("denied", "backend", "frontend")}
    if tools is not None:
        t = _json(tools)
        if not isinstance(t.get("tools"), list):
            raise GateFault(f"{tools} lists no tools — a pack declares {{\"tools\": [{{\"name\", \"version\"}}]}}")
        adds["tools"] = (str(tools), t["tools"])
    denied = {key(e["name"]) for d, e in _entries(allow) if d}
    listed = {key(e["name"]) for _, e in _entries(allow)}
    added = 0
    for cat, (where, items) in adds.items():
        for x in items:
            e = _entry(x, where)
            k = key(e["name"])
            if k in (denied if cat == "denied" else listed):
                continue
            allow.setdefault(cat, []).append(e)
            listed.add(k)
            denied |= {k} if cat == "denied" else set()
            added += 1
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(allow, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return {"allowlist": ALLOWLIST, "added": added}
